"""G8 closeout numeric appendix -> docs/cv/gauntlet/G8_results_autogen.md (+ ml/runs/G8/closeout_summary.json). Missing inputs print 'pending / not measured'."""
import json, os
B = "/workspace/work/nutrisole"; R = f"{B}/ml/runs"
def lj(p):
    p = p if p.startswith("/") else f"{R}/{p}"
    return json.load(open(p)) if os.path.exists(p) else None
def f(x, n=3): return "n/a" if x is None else (f"{x:.{n}f}" if isinstance(x, float) else str(x))
S = {}; L = ["# G8 results appendix (auto-generated by ml/runs/G8/scripts/g8_report.py)", "",
     "Every number states split / n / model / imgsz / device. Nothing here is phone, emulator, Lahore, or box-level human verification. 'pending' / 'n/a' = the job had not finished or the item is not measurable.", ""]
# A. image metrics
g3s = {**(lj("G3/eval_det_k11_480/eval_det.json") or {}), }
def rows(d): return {r["split"]: r for r in (d or {}).get("results", [])}
G3 = {}
for p in ["G3/eval_det_k11_480/eval_det.json", "G4/eval_det_G3champ_oiv7c/eval_det.json", "G3/eval_pooled_k11_480/eval_det.json"]:
    G3.update(rows(lj(p)))
M = {"G3 control (champion, historical CPU eval files)": G3}
for s in (0, 1):
    d = rows(lj(f"G8/showcase/eval_splits_show_s{s}/eval_det.json")); d.update(rows(lj(f"G8/showcase/eval_pooled_show_s{s}/eval_det.json"))); M[f"showcase s{s} (5-class, expanded to 12 rows)"] = d
SP = ["test", "test_rf", "test_oiv7", "test_oiv7c", "pooled"]
L += ["## A. Locked image splits (sandbox CPU, PyTorch .pt via ml/eval/eval_det.py, imgsz 480, conf 0.001, iou 0.7)", "",
      "12-class mAP is shown for completeness; the showcase model has 7 classes zeroed by design, so its 12-class mean is not comparable. Compare per class.", "",
      "| model | " + " | ".join(f"{s} mAP50 / 50-95" for s in SP) + " |", "|---|" + "---|" * len(SP)]
for k, d in M.items():
    L.append(f"| {k} | " + " | ".join((f"{d[s]['mAP50']:.3f} / {d[s]['mAP50_95']:.3f}" if s in d else "pending") for s in SP) + " |")
SHOW = ["citrus", "apple", "banana", "tomato", "carrot"]
L += ["", "Per-class mAP50 on the 5 showcase classes (strict per split, then pooled n=829):", "", "| split | class | inst | G3 | s0 | s1 | s0-G3 | s1-G3 |", "|---|---|---|---|---|---|---|---|"]
S["per_class"] = {}
for sp in SP:
    for c in SHOW:
        g = G3.get(sp, {}).get("per_class", {}).get(c); a = M["showcase s0 (5-class, expanded to 12 rows)"].get(sp, {}).get("per_class", {}).get(c); b = M["showcase s1 (5-class, expanded to 12 rows)"].get(sp, {}).get("per_class", {}).get(c)
        if not g: continue
        L.append(f"| {sp} | {c} | {g['instances']} | {g['mAP50']:.3f} | {f(a and a['mAP50'])} | {f(b and b['mAP50'])} | {f(a and round(a['mAP50']-g['mAP50'],3))} | {f(b and round(b['mAP50']-g['mAP50'],3))} |")
        S["per_class"][f"{sp}/{c}"] = dict(inst=g["instances"], g3=g["mAP50"], s0=a and a["mAP50"], s1=b and b["mAP50"])
nf = lj("G8/showcase/neg_fa_show_s0.json"); g3nf = lj("G3/neg_fa_k11_480.json")
def nfa(d):
    if not d: return None
    r = list(d.get("results", {}).values())
    return (f"{r[0].get('images_with_false_alarm')}/{d.get('n')} images" + (f" (rate {r[0].get('fa_image_rate')})" if 'fa_image_rate' in r[0] else "")) if r else json.dumps(d)[:160]
L += ["", f"neg_test image FA (n=80, score 0.35): G3 {nfa(g3nf)}; showcase s0 {nfa(nf) if nf else 'pending'}", ""]
# B. showcase decision
dec = lj("G8/showcase/decision.json") or {}
L += ["## B. Showcase decision (Addendum 2026-10-13 S3)", "", f"criteria: {json.dumps(dec.get('criteria'))}; PASS = {dec.get('PASS')}; passing classes s0 = {dec.get('claimable_classes_seed0')}", ""]
lat = lj("G8/showcase/latency.json")
L += [f"Latency (sandbox CPU, onnxruntime, det session.run, 100 val frames x2 interleaved): {json.dumps(lat) if lat else 'pending'}", ""]
par = lj("G8/showcase/parity_show_s0.json"); L += [f"ONNX parity show_s0 (raw 480, 40 val imgs): {('pass=' + str(par['detector']['pass']) + ', class disagreements ' + str(par['detector']['class_disagreements']) + ', min IoU ' + str(round(par['detector']['min_iou'],5))) if par else 'pending'}", ""]
pcb = lj("G8/showcase/perclass_bootstrap_s0.json"); L += ["Per-class source-level bootstrap (pooled n=829, B=1000) s0 - G3 mAP50: " + ("; ".join(f"{c} {v['point']:+.3f} CI95 {v['ci95']}" for c, v in pcb["splits"]["pooled"]["diff_ci95"].items()) if pcb else "pending"), ""]
# C. dev video
L += ["## C. DEV video (g3clips_dev det + neg, synthetic from G3 dev images, sandbox CPU, fixed-frame, IouTracker unless stated)", "",
      "| run | det segment acc | frame acc | TTFC p50 / p90 ms | ID switches | fragmentations | static flicker /10 s | neg FA/min | full latency p50 / p95 ms |", "|---|---|---|---|---|---|---|---|---|"]
S["dev_video"] = {}
for k, p in [("G3", "G8/showcase/video_dev_G3"), ("G3r5 (G3, 5 showcase rows)", "G8/showcase/video_dev_G3r5"), ("showcase s0", "G8/showcase/video_dev_show_s0"), ("G3 + ByteTrack DEV pick nt0.25_mt0.8_mh1", "G7/tracking/tune/nt0.25_mt0.8_mh1")]:
    g = lj(f"{p}/gauntlet.json")
    if not g: L.append(f"| {k} | pending |||||||| "); continue
    c, n = g["clips"]["det"], g["clips"].get("neg", {})
    S["dev_video"][k] = dict(seg=c["segment_acc"], ttfc_p90=c["ttfc_ms"]["p90"], ids=c["id_switches"], frag=c.get("fragmentations"), fa=n.get("false_alarms_per_min"))
    L.append(f"| {k} | {c['segment_acc']} | {c['frame_acc']} | {f(c['ttfc_ms']['p50'],0)} / {f(c['ttfc_ms']['p90'],0)} | {c['id_switches']} | {c.get('fragmentations')} | {c['label_flicker_per_10s_static']} | {n.get('false_alarms_per_min')} | {f(c['latency_full_ms']['p50'],1)} / {f(c['latency_full_ms']['p95'],1)} |")
pk = lj("G8/tracking/pick_g7grid.json")
L += ["", f"Tracker DEV grid (G7 addendum-C rule, unchanged): {len(pk['rows'])}/8 configs, pick = {pk['pick']} (ref {pk['ref']})." if pk else "tracker grid pending", ""]
tt = lj("G8/tracking/test_tuned_r1/gauntlet.json"); nt = lj("G8/tracking/negtest_tuned_r1/gauntlet.json")
if tt: 
    c = tt["clips"]; L.append(f"Tracker pick on historical TEST gauntlet (g1clips, r1): det seg {c['det']['segment_acc']}, rotten seg recall {c.get('quality',{}).get('rotten_segment_recall')}, G1 neg FA/min {c.get('neg',{}).get('false_alarms_per_min')}, static flicker {c['det']['label_flicker_per_10s_static']}, ID switches {c['det']['id_switches']}")
else: L.append("Tracker pick on historical TEST gauntlet (g1clips): pending / not completed")
if nt: L.append(f"Tracker pick G2 negtest FA/min {nt['clips']['neg']['false_alarms_per_min']}.")
L.append("")
# D. holdout
H = lj("G8/holdout/holdout_scores.json")
L += ["## D. VB8-holdout, clip-level (prereg addendum 2026-10-14; Kaggle free CPU replay, onnxruntime 1 thread, ~10 fps fixed-frame)", ""]
if H:
    L += open(f"{R}/G8/holdout/holdout_scores.md").read().splitlines()
    S["holdout"] = {v: {c: dict(recall=H[v][c]["clip_presence_recall"], pairs=H[v][c]["pairs_n"], fa=H[v][c]["fa_per_min"], ttfc=H[v][c]["ttfc_proxy_s"], births=H[v][c]["track_births_per_min_positive"], frag=H[v][c]["frag_proxy_tracks_per_detected_pair"], lab=H[v][c]["label_changes_per_track_min"]) for c in H[v]} for v in ("all12", "show5")}
    S["holdout_boot"] = H["bootstrap"]
else: L.append("pending (Kaggle kernel mfaizannnn/nutrisole-g8-holdout not collected)")
L.append("")
# E. ripeness / night / tests / hashes
hs = lj("G8/hue_shift/ripeness_hue_shift.json"); rd = lj("G7/ripeness/ripeness_dedup.json"); ng = lj("G7/night/night_gate.json")
L += ["## E. Ripeness, defects, night", ""]
if rd: L.append(f"Ripeness (G7 per-fruit head, unchanged in G8; test_cc0, Kaggle T4 preds): all n={rd['all']['n']} top1 {rd['all']['top1_15way']}; de-duplicated (pHash <= 4 to train removed) n={rd['dedup']['n']} top1 {rd['dedup']['top1_15way']}; per fruit dedup: " + ", ".join(f"{k} {v['top1']} (n={v['n']})" for k, v in rd['dedup']['per_fruit'].items()))
if hs: L.append("Hue-shift sweep (G8, Kaggle CPU, same head): " + "; ".join(f"{r['hue_shift_deg']:+d} deg stage acc dedup {r['dedup_stage_acc']} overripe recall dedup {r['dedup_overripe_recall']}" for r in hs["rows"]))
L.append("Grouping by independent capture source/session and across lighting/variety: not measurable with test_cc0 (no session metadata); visible-defect agreement: not measured (no independently labelled defect set in G8).")
L.append(f"Night classifier (G7 kernel nutrisole-g7-night): {'gate rows: ' + json.dumps(ng['models']) if ng and ng.get('models') else 'PENDING (Kaggle kernel still RUNNING at closeout)'}")
L.append("")
ts = f"{R}/G8/tests_summary.txt"; lh = lj("G8/locked_hashes_end.json")
L += ["## F. Repo tests and locked-split integrity", "", f"Tests: {open(ts).read().strip().replace(chr(10), '; ') if os.path.exists(ts) else 'pending'}"]
if lh:
    L.append("Locked hashes vs ml/runs/G6/locked_hashes.json: " + ", ".join(f"{k} n={v['n']} identical={v['identical_to_g5']}" for k, v in lh.items() if isinstance(v, dict) and "n" in v) + f"; gauntlet clips identical={lh.get('clips_identical_to_g5')}")
else: L.append("Locked hashes: pending")
open(f"{B}/docs/cv/gauntlet/G8_results_autogen.md", "w").write("\n".join(L) + "\n")
json.dump(S, open(f"{R}/G8/closeout_summary.json", "w"), indent=1, default=str)
print("\n".join(L))
